system_context = "I am learning {language} and want to create flashcards. For this I need to get the value of certain fields. Provide all answers in {language}, no English translations or explanations. Ensure your responses contain nothing but the required information as your responses will be directly written to a flashcard."
definition_prompt= "Provide a short, single-sentence definition of the word \"{word}\" in {language}. Your response must be entirely in {language}. Include only the definition—no translation, explanation, or additional context. Include nothing else in your response."
example_prompt = " Use \"{word}\" in one short sentence in {language} to illustrate to a user how it is used. Your response must contain nothing else."
emotional_colour_prompt = "Describe the feelings that \"{word}\" evokes in {language}. Answer as a short fragment, not a sentence. Your response must contain nothing else."
usage_conditions_prompt = "State when \"{word}\" is used in {language} — the situations, relationships and register it suits. Answer as a short fragment, not a sentence. Your response must contain nothing else."
notable_use_prompt = "If \"{word}\" appears in a well-known saying, proverb, work of literature, speech or song in {language}, quote that use in one line. If there is no such use, reply with exactly NONE — in English, untranslated. Never invent a use. Your response must contain nothing else."
lyric_prompt = "Quote one line from a well-known song in {language} that contains \"{word}\". Give the line only, with no title or artist. Your response must contain nothing else."